// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 d, uint256 v) public {
        d = bound(d, 1, type(uint128).max);
        v = bound(v, 1, d);

        // fund this test contract (it is c.owner) and deposit d into c via fallback
        vm.deal(address(this), d);
        (bool depOk, ) = address(c).call{value: d}("");
        assertTrue(depOk);

        uint256 before = address(c).balance;

        // owner withdraws exactly v; the test contract accepts ETH via receive()
        vm.prank(address(this));
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.withdraw.selector, v));

        // Rule: an admissible withdraw(v) (v <= balance) succeeds and deducts exactly v wei.
        assertTrue(ok && (before - address(c).balance) == v);
    }
}
